    private void EnsureTraditionalDiceTray()
    {
        if (traditionalDiceTray != null)
            return;

        traditionalDiceTray =
            GetComponent<TraditionalDiceTray3D>();

        if (traditionalDiceTray == null)
        {
            traditionalDiceTray =
                gameObject.AddComponent<
                    TraditionalDiceTray3D
                >();
        }

        traditionalDiceTray.Initialize(this);
    }

    private void OpenTraditionalDicePrompt(
        int suggestedDice)
    {
        if (IsXcomMode)
            return;

        EnsureTraditionalDiceTray();

        traditionalDiceTray
            .SetRequestedDiceCount(
                Mathf.Max(
                    1,
                    suggestedDice
                )
            );

        showDiceTray = true;
    }

    private bool TraditionalStateResolutionPending()
    {
        return
            !IsXcomMode &&
            (traditionalFirstTurnPending ||
             traditionalNumericPromptPending ||
             traditionalAdvancePending ||
             traditionalChargePending ||
             traditionalBattleShockPending ||
             traditionalBattleShockQueue.Count > 0 ||
             traditionalReanimationPending ||
             traditionalRuleAlertPending);
    }

    private void OpenTraditionalNumericPrompt(
        string title,
        string text,
        int minimum,
        int maximum,
        int initial,
        int suggestedDice,
        System.Action<int> apply,
        System.Action cancel = null)
    {
        if (IsXcomMode)
            return;

        traditionalNumericPromptPending = true;
        traditionalNumericTitle =
            string.IsNullOrWhiteSpace(
                title)
            ? "TRADITIONAL RESULT"
            : title;
        traditionalNumericText =
            text ?? "";
        traditionalNumericMin =
            minimum;
        traditionalNumericMax =
            Mathf.Max(
                minimum,
                maximum
            );
        traditionalNumericValue =
            Mathf.Clamp(
                initial,
                traditionalNumericMin,
                traditionalNumericMax
            );
        traditionalNumericApply = apply;
        traditionalNumericCancel = cancel;

        OpenTraditionalDicePrompt(
            suggestedDice
        );

        status =
            traditionalNumericTitle +
            ": resolve the dice yourself, then enter the final value.";
    }

    private void CompleteTraditionalNumericPrompt()
    {
        if (!traditionalNumericPromptPending)
            return;

        int value =
            Mathf.Clamp(
                traditionalNumericValue,
                traditionalNumericMin,
                traditionalNumericMax
            );

        string title =
            traditionalNumericTitle;

        System.Action<int> apply =
            traditionalNumericApply;

        traditionalNumericPromptPending = false;
        traditionalNumericTitle = "";
        traditionalNumericText = "";
        traditionalNumericApply = null;
        traditionalNumericCancel = null;

        AppendBattleLog(
            "MANUAL RESULT",
            title,
            "Player entered final value " +
            value +
            ". Warboard did not inspect the physical dice."
        );

        if (apply != null)
            apply(value);
    }

    private void CancelTraditionalNumericPrompt()
    {
        if (!traditionalNumericPromptPending)
            return;

        System.Action cancel =
            traditionalNumericCancel;

        traditionalNumericPromptPending = false;
        traditionalNumericTitle = "";
        traditionalNumericText = "";
        traditionalNumericApply = null;
        traditionalNumericCancel = null;

        if (cancel != null)
            cancel();

        status =
            "Traditional manual result prompt cancelled.";
    }

    private void CompleteTraditionalFirstTurnRollOff(
        int winnerIndex)
    {
        if (!traditionalFirstTurnPending ||
            winnerIndex < 0 ||
            winnerIndex >= factions.Count)
        {
            return;
        }

        traditionalFirstTurnPending = false;

        firstTurnFactionIndex =
            winnerIndex;

        activeFactionIndex =
            firstTurnFactionIndex;

        activeFaction =
            factions[
                activeFactionIndex
            ];

        firstTurnRollSummary =
            ActiveFactionDisplayName() +
            " won the manually resolved first-turn roll-off and takes first turn.";

        AppendBattleLog(
            "ROLL-OFF",
            "First turn",
            firstTurnRollSummary
        );

        StartFactionBattleRoundRules();

        CaptureObjectiveControlAtPhaseStart();
        ClearPhaseDestructionRecords();

        BeginActiveTurn(
            true
        );
    }

    private void BeginNextTraditionalBattleShock()
    {
        if (IsXcomMode)
            return;

        while (traditionalBattleShockQueue.Count > 0)
        {
            SquadController unit =
                traditionalBattleShockQueue.Dequeue();

            if (unit == null ||
                !unit.IsAlive ||
                !unit.IsOnBattlefield)
            {
                continue;
            }

            traditionalBattleShockUnit =
                unit.JoinedActionController();

            traditionalBattleShockPending =
                true;

            if (Core11OfferInsaneBraveryForTraditionalBattleShock(
                    traditionalBattleShockUnit))
            {
                return;
            }

            OpenTraditionalDicePrompt(
                2
            );

            status =
                "BATTLE-SHOCK TEST REQUIRED: " +
                traditionalBattleShockUnit.DisplayName +
                ". Roll 2D6 manually, apply any tabletop rules yourself, then mark PASS or FAIL.";

            return;
        }

        traditionalBattleShockPending = false;
        traditionalBattleShockUnit = null;

        status =
            "All required Traditional Battle-shock tests have been marked.";
    }

    private void CompleteTraditionalBattleShock(
        bool passed)
    {
        if (!traditionalBattleShockPending ||
            traditionalBattleShockUnit == null)
        {
            return;
        }

        SquadController unit =
            traditionalBattleShockUnit;

        int leadership =
            EffectiveLeadership(
                unit
            );

        unit.SetBattleShocked(
            !passed,
            0
        );

        AppendBattleLog(
            "BATTLE-SHOCK",
            unit.DisplayName,
            traditionalBattleShockLabel +
            "  |  Leadership " +
            leadership +
            "+  |  player marked " +
            (passed
                ? "PASS"
                : "FAIL  -  BATTLE-SHOCKED") +
            ". Physical dice were not interpreted by Warboard."
        );

        traditionalBattleShockPending = false;
        traditionalBattleShockUnit = null;

        BeginNextTraditionalBattleShock();
        RefreshObjectiveDisplays();
    }

    private void HandleLoggedDiceRoll(
        DiceRollRecord record)
    {
        if (record == null)
            return;

        string results =
            record.Results != null &&
            record.Results.Length > 0
            ? "[" +
              string.Join(
                  ", ",
                  record.Results
                      .Select(
                          value =>
                              value.ToString()
                      )
                      .ToArray()
              ) +
              "]"
            : "[]";

        AppendBattleLog(
            "ROLL",
            record.Label,
            results +
            " = " +
            record.Total
        );
    }

    private void CompleteTraditionalAdvance()
    {
        if (!traditionalAdvancePending ||
            traditionalAdvanceUnit == null)
        {
            traditionalAdvancePending = false;
            traditionalAdvanceUnit = null;
            return;
        }

        SquadController unit =
            traditionalAdvanceUnit;

        int result =
            Mathf.Clamp(
                traditionalAdvanceResult,
                1,
                6
            );

        traditionalAdvancePending = false;
        traditionalAdvanceUnit = null;

        ApplyAdvanceRoll(
            unit,
            result
        );

        AppendBattleLog(
            "ADVANCE",
            unit.DisplayName,
            "Player-entered final Advance result: +" +
            result +
            ". Warboard did not interpret or validate the physical dice."
        );

        status =
            unit.DisplayName +
            " Advance set to +" +
            result +
            ".";
    }

    private void CancelTraditionalAdvance()
    {
