    }

    public int RollTabletopD3(
        string label)
    {
        int raw =
            DiceRoller.RollD6(
                label +
                " (D3)"
            );

        return Mathf.CeilToInt(
            raw / 2f
        );
    }

    private string TraditionalAttackSelectionSummary(
        List<WeaponAttackSelection> selections)
    {
        if (selections == null ||
            selections.Count == 0)
        {
            return "No weapon profile";
        }

        return string.Join(
            " | ",
            selections
                .Where(
                    selection =>
                        selection != null &&
                        selection.weapon != null
                )
                .Select(
                    selection =>
                    {
                        WeaponData weapon =
                            selection.weapon;

                        string attacks =
                            string.IsNullOrWhiteSpace(
                                weapon.attacksExpression)
                            ? weapon.attacksPerModel
                                .ToString()
                            : weapon.attacksExpression;

                        string damage =
                            string.IsNullOrWhiteSpace(
                                weapon.damageExpression)
                            ? weapon.damage.ToString()
                            : weapon.damageExpression;

                        return
                            (selection.model != null
                                ? selection.model.RoleName +
                                  ": "
                                : "") +
                            weapon.displayName +
                            "  |  A " +
                            attacks +
                            "  |  S " +
                            weapon.strength +
                            "  |  AP " +
                            weapon.ap +
                            "  |  D " +
                            damage;
                    }
                )
                .ToArray()
        );
    }

    private void BeginTraditionalAttackDeclaration(
        SquadController attacker,
        SquadController target,
        List<WeaponAttackSelection> selections,
        AttackMode attackMode,
        bool engagedShooting)
    {
        if (traditionalAttackPending)
        {
            status =
                "Finish the currently declared Traditional attack first.";
            return;
        }

        traditionalAttackPending = true;
        traditionalAttackAttacker = attacker;
        traditionalAttackTarget = target;
        traditionalAttackSelections =
            selections != null
            ? new List<WeaponAttackSelection>(
                selections
              )
            : new List<WeaponAttackSelection>();
        traditionalAttackMode = attackMode;
        traditionalAttackConsumesAction =
            interactiveAttackConsumesNormalAction;
        traditionalAttackModelLevel =
            interactiveAttackModelLevelShooting;
        traditionalAttackCompletionCallback =
            interactiveAttackCompletionCallback;

        if (attackMode ==
            AttackMode.Ranged)
        {
            foreach (WeaponAttackSelection selection
                in traditionalAttackSelections)
            {
                if (selection == null ||
                    selection.model == null ||
                    selection.weapon == null)
                {
                    continue;
                }

                selection.model.MarkWeaponUsed(
                    selection.weapon
                );

                if (traditionalAttackModelLevel)
                {
                    selection.model
                        .MarkRangedWeaponFiredThisTurn(
                            selection.weapon
                        );
                }
            }
        }

        showDiceTray = true;
        manualWoundEditMode = true;
        EnsureTraditionalDiceTray();

        string weaponSummary =
            TraditionalAttackSelectionSummary(
                traditionalAttackSelections
            );

        AppendBattleLog(
            attackMode == AttackMode.Ranged
            ? "SHOOTING DECLARATION"
            : "FIGHT DECLARATION",
            attacker.DisplayName +
            "  ->  " +
            target.DisplayName,
            weaponSummary +
            ". Traditional mode: dice and damage are entirely player-resolved."
        );

        status =
            "TRADITIONAL: " +
            attacker.DisplayName +
            "  ->  " +
            target.DisplayName +
            "  |  " +
            weaponSummary +
            ". Use the free 3D dice tray and manual wound controls, then click ATTACK RESOLVED." +
            (engagedShooting
                ? " PISTOLS/CLOSE-QUARTERS ONLY."
                : "");
    }

    private void CompleteTraditionalAttackDeclaration()
    {
        if (!traditionalAttackPending)
            return;

        SquadController attacker =
            traditionalAttackAttacker;
        SquadController target =
            traditionalAttackTarget;
        AttackMode attackMode =
            traditionalAttackMode;
        bool consumeAction =
            traditionalAttackConsumesAction;
        bool modelLevel =
            traditionalAttackModelLevel;
        System.Action completion =
            traditionalAttackCompletionCallback;

        List<string> hazardousWeapons =
            traditionalAttackSelections
                .Where(
                    selection =>
                        selection != null &&
                        selection.weapon != null &&
                        WeaponRuleParser.Has(
                            selection.weapon,
                            "hazardous"
                        )
                )
                .Select(
                    selection =>
                        selection.weapon.displayName
                )
                .Distinct()
                .ToList();

        traditionalAttackPending = false;
        traditionalAttackAttacker = null;
        traditionalAttackTarget = null;
        traditionalAttackSelections.Clear();
        traditionalAttackConsumesAction = true;
        traditionalAttackModelLevel = false;
        traditionalAttackCompletionCallback = null;

        interactiveAttackCompletionCallback = null;
        interactiveAttackConsumesNormalAction = true;
        interactiveAttackSuppressesPostReactions = false;
        interactiveAttackModelLevelShooting = false;

        if (attacker != null)
        {
            if (attackMode ==
                AttackMode.Ranged)
            {
                if (modelLevel)
                {
                    RefreshModelLevelShootingState(
                        attacker
                    );
                }
                else if (consumeAction)
                {
                    attacker.HasShot = true;

                    if (attacker.AttachedLeader != null)
                    {
                        attacker.AttachedLeader.HasShot = true;
                    }
                }
            }
            else if (consumeAction)
            {
                attacker.HasFought = true;

                if (attacker.AttachedLeader != null)
                {
                    attacker.AttachedLeader.HasFought = true;
                }

                if (attacker.IsAlive)
                {
                    SquadController consolidationTarget =
                        FindNearestEnemy(attacker);

                    if (consolidationTarget != null)
                    {
                        AutoMoveSquadToward(
                            attacker,
                            consolidationTarget,
                            attacker.SuddenStrikeActive
                                ? 6f
                                : ConsolidateDistance,
                            0.86f
                        );
                    }
                }

                attacker.KatahSustainedActive = false;
                attacker.KatahLethalActive = false;

                AdvanceFightPriority(
                    attacker
                );
            }
        }

        GameEventBus.Raise(
            new GameEventContext
            {
                Type =
                    GameEventType.AttackResolved,
                Game = this,
                ActingFaction =
                    attacker != null
                    ? attacker.FactionId
                    : activeFaction,
                Phase = phase,
                Source = attacker,
                Target = target,
                AttackMode = attackMode,
                Amount = 0
            }
        );

        AppendBattleLog(
            attackMode == AttackMode.Ranged
            ? "SHOOTING"
            : "MELEE",
            "Traditional attack resolved",
            "Dice and damage were resolved manually by the players. Warboard changed no wounds automatically."
        );

        if (hazardousWeapons.Count > 0)
        {
            QueueTraditionalRuleAlert(
                "HAZARDOUS",
                "The resolved attack used: " +
                string.Join(
                    ", ",
                    hazardousWeapons.ToArray()
                ) +
                ". Resolve all required Hazardous rolls yourself and manually apply any wounds/models.",
                Mathf.Max(
                    1,
                    hazardousWeapons.Count
                )
            );
        }

        HandleBodyguardDestroyed(target);
        HandleBodyguardDestroyed(attacker);
        RefreshObjectiveDisplays();

        manualWoundEditMode =
            traditionalRuleAlertPending;
        pendingTraditionalRemovalCandidate = null;

        if (completion != null)
        {
            completion();
        }
        else
        {
            status =
                "Traditional attack marked RESOLVED. No dice or damage were interpreted by Warboard.";
        }
    }

    private List<ModelToken>
        TraditionalRestoreCandidates()
    {
        if (selectedSquad == null)
        {
            return new List<ModelToken>();
        }

        SquadController unit =
            selectedSquad
                .JoinedActionController();

        List<ModelToken> dead =
            unit.DestroyedModelTokens()
                .Where(
                    model =>
                        model != null
                )
                .ToList();

        if (unit.AttachedLeader != null)
        {
            dead.AddRange(
                unit.AttachedLeader
                    .DestroyedModelTokens()
                    .Where(
                        model =>
                            model != null
                    )
            );
        }

        return dead;
    }

    private void CycleTraditionalRestoreCandidate(
        int direction)
    {
        List<ModelToken> dead =
            TraditionalRestoreCandidates();

        if (dead.Count == 0)
        {
            manualRestoreDeadIndex = 0;
            return;
        }

        manualRestoreDeadIndex =
            (manualRestoreDeadIndex +
             direction) %
            dead.Count;

        if (manualRestoreDeadIndex < 0)
        {
            manualRestoreDeadIndex +=
                dead.Count;
        }
    }

    private void TraditionalRestoreCurrentModel(
        bool fullWounds)
    {
        if (IsXcomMode ||
            selectedSquad == null)
        {
            return;
        }

        List<ModelToken> dead =
            TraditionalRestoreCandidates();

        if (dead.Count == 0)
        {
            status =
                selectedSquad.DisplayName +
                " has no destroyed models to restore.";
            return;
        }

        manualRestoreDeadIndex =
            Mathf.Clamp(
                manualRestoreDeadIndex,
                0,
                dead.Count - 1
            );

        ModelToken returning =
            dead[
                manualRestoreDeadIndex
            ];

        SquadController owner =
            returning.Squad;

        if (owner == null)
            return;

        Vector3 position;

        if (!TryFindReanimationPosition(
                owner,
                returning,
                out position))
        {
            // For an Attached Leader with no other living Leader model,
            // use the joined Bodyguard as the placement anchor.
            SquadController joined =
                selectedSquad
                    .JoinedActionController();

            if (!TryFindReanimationPosition(
                    joined,
                    returning,
                    out position))
            {
                status =
                    "No legal nearby placement was found for " +
                    returning.RoleName +
                    ".";
                return;
            }
        }

        int wounds =
            fullWounds
            ? returning.MaxWounds
            : 1;

        returning.Revive(
            wounds,
            position
        );

        owner.RefreshVisuals();

        SquadController joinedUnit =
            selectedSquad
                .JoinedActionController();

        joinedUnit.RefreshVisuals();
        RefreshObjectiveDisplays();

        AppendBattleLog(
            "RESTORE",
            joinedUnit.DisplayName,
            returning.RoleName +
            " manually returned at " +
            wounds +
            "/" +
            returning.MaxWounds +
            " wounds. Warboard did not determine whether a rule permitted this."
        );

        manualRestoreDeadIndex = 0;

        status =
            returning.RoleName +
            " manually returned at " +
            wounds +
            " wound(s).";
    }

    private void TraditionalAdjustSelectedWounds(
        int delta)
    {
        if (IsXcomMode ||
            selectedModel == null ||
            !selectedModel.IsAlive ||
            delta == 0)
        {
            return;
        }

        if (delta < 0 &&
            selectedModel.CurrentWounds <=
                -delta)
        {
            TryTraditionalRemoveSelectedModel();
            return;
        }

        int before =
            selectedModel.CurrentWounds;

        if (delta < 0)
        {
            selectedModel.ApplyDamage(
                -delta
            );
        }
        else
        {
            selectedModel.Heal(
                delta
            );
        }

        int after =
            selectedModel.CurrentWounds;

        selectedModel.RefreshWoundDisplay();

        AppendBattleLog(
            "WOUNDS",
            selectedModel.RoleName,
            before +
            "  ->  " +
            after +
            " wounds (manual Traditional adjustment)."
        );

        status =
            selectedModel.RoleName +
            ": " +
            after +
            "/" +
            selectedModel.MaxWounds +
            " wounds.";
    }

    private void TryTraditionalRemoveSelectedModel()
    {
        if (IsXcomMode ||
            selectedModel == null ||
            !selectedModel.IsAlive)
        {
            return;
        }

        SquadController actionUnit =
            selectedModel.Squad != null
            ? selectedModel.Squad
                .JoinedActionController()
            : null;

        if (actionUnit != null &&
            !actionUnit
                .WouldRemainCoherentAfterRemoving(
                    selectedModel
                ))
        {
            pendingTraditionalRemovalCandidate =
                selectedModel;

            status =
                "COHERENCY WARNING: removing " +
                selectedModel.RoleName +
                " will leave the unit out of coherency. Choose another model or click REMOVE ANYWAY.";

            return;
        }

        ConfirmTraditionalModelRemoval(
            selectedModel
        );
    }

    private void ConfirmTraditionalModelRemoval(
        ModelToken model)
    {
        if (model == null ||
            !model.IsAlive)
        {
            return;
        }

        SquadController unit =
            model.Squad != null
            ? model.Squad
                .JoinedActionController()
            : null;

        string role = model.RoleName;
        string squadName =
            model.Squad != null
            ? model.Squad.DisplayName
            : "Unit";

        model.ApplyDamage(
            model.CurrentWounds
        );

        RecordModelDestroyed(
            model,
            traditionalAttackPending
            ? traditionalAttackAttacker
            : null
        );

        QueueTraditionalDeathTrigger(
            model
        );

        int coherencyLosses =
            ResolveTraditionalForcedCoherencyLosses(
                unit,
                traditionalAttackPending
                ? traditionalAttackAttacker
                : null
            );

        AppendBattleLog(
            "CASUALTY",
            squadName,
            role +
            " removed manually." +
            (coherencyLosses > 0
                ? " " +
                  coherencyLosses +
                  " additional model(s) removed for Unit Coherency."
                : "")
        );

        pendingTraditionalRemovalCandidate = null;
        selectedModel = null;

        HandleBodyguardDestroyed(unit);
        RefreshObjectiveDisplays();

        status =
            role +
            " removed manually." +
            (coherencyLosses > 0
                ? " " +
                  coherencyLosses +
                  " additional model(s) removed to restore coherency."
                : " Resolve any death-triggered rules manually.");
    }

    private int ResolveTraditionalForcedCoherencyLosses(
        SquadController unit,
        SquadController attacker)
    {
        if (unit == null)
            return 0;

        SquadController actionUnit =
            unit.JoinedActionController();

        int removed = 0;
        int guard = 0;

        while (actionUnit.IsAlive &&
               !actionUnit.IsCoherent() &&
               guard < 64)
        {
            guard++;

            ModelToken casualty =
                actionUnit
                    .IncoherentModels()
                    .Where(
                        model =>
                            model != null &&
                            model.IsAlive
                    )
                    .OrderByDescending(
                        model =>
                            HorizontalDistance(
                                model.transform.position,
                                actionUnit.CurrentCentre()
                            )
                    )
                    .FirstOrDefault();

            if (casualty == null)
                break;

            casualty.ApplyDamage(
                casualty.CurrentWounds
            );

            RecordModelDestroyed(
                casualty,
                attacker
            );

            QueueTraditionalDeathTrigger(
                casualty
            );

            removed++;
        }

        actionUnit.RefreshVisuals();

        if (actionUnit.AttachedLeader != null)
        {
            actionUnit.AttachedLeader
                .RefreshVisuals();
        }

        return removed;
    }

    private void QueueTraditionalRuleAlert(
        string title,
        string text,
        int suggestedDice,
        System.Action completion = null)
    {
        if (IsXcomMode)
            return;

        if (completion != null)
        {
            System.Action previous =
                traditionalRuleAlertCompletion;

            traditionalRuleAlertCompletion =
                previous == null
                ? completion
                : () =>
                {
                    previous();
                    completion();
                };
        }

        if (traditionalRuleAlertPending)
        {
            traditionalRuleAlertText +=
                "\n\n" +
                title +
                ": " +
                text;

            traditionalRuleAlertSuggestedDice =
                Mathf.Max(
                    traditionalRuleAlertSuggestedDice,
                    suggestedDice
                );
        }
        else
        {
            traditionalRuleAlertPending = true;
            traditionalRuleAlertTitle =
                title ?? "TRIGGERED RULE";
            traditionalRuleAlertText =
                text ?? "";
            traditionalRuleAlertSuggestedDice =
                Mathf.Max(
                    0,
                    suggestedDice
                );
        }

        if (traditionalRuleAlertSuggestedDice > 0)
        {
            OpenTraditionalDicePrompt(
                traditionalRuleAlertSuggestedDice
            );
        }

        AppendBattleLog(
            "TRIGGER",
            traditionalRuleAlertTitle,
            text +
            " Resolve this rule manually in Traditional mode."
        );
    }

    private void AcknowledgeTraditionalRuleAlert()
    {
        traditionalRuleAlertPending = false;
        traditionalRuleAlertTitle = "";
        traditionalRuleAlertText = "";
        traditionalRuleAlertSuggestedDice = 1;

        System.Action completion =
            traditionalRuleAlertCompletion;

        traditionalRuleAlertCompletion = null;

        status =
            "Triggered-rule reminder acknowledged. Apply any resulting wounds/models manually.";

        if (completion != null)
        {
            completion();
        }
        else if (endPhaseFlowRunning)
        {
            ContinueEndPhaseFlow();
        }
    }

    private void QueueTraditionalDeathTrigger(
        ModelToken destroyedModel)
    {
        if (IsXcomMode ||
            destroyedModel == null ||
            destroyedModel.Squad == null)
        {
            return;
        }

        string expression =
            UniversalRuleRegistry
                .GetDeadlyDemiseExpression(
                    destroyedModel.Squad
                );

        if (string.IsNullOrWhiteSpace(
                expression))
        {
            return;
        }

        QueueTraditionalRuleAlert(
            "DEADLY DEMISE",
            destroyedModel.Squad.DisplayName +
            " has Deadly Demise " +
            expression +
            ". Roll the trigger and any resulting mortal wounds yourself, then use WOUND EDIT / REMOVE to apply the outcome.",
            1
        );
    }

    private void CompleteTraditionalCharge()
    {
        if (!traditionalChargePending ||
            traditionalChargeAttacker == null ||
            traditionalChargeTarget == null)
        {
            traditionalChargePending = false;
            traditionalChargeAttacker = null;
            traditionalChargeTarget = null;
            return;
        }

        SquadController attacker =
            traditionalChargeAttacker;

        SquadController target =
            traditionalChargeTarget;

        int result =
            Mathf.Clamp(
                traditionalChargeResult,
                2,
                12
            );

        traditionalChargePending = false;
        traditionalChargeAttacker = null;
        traditionalChargeTarget = null;

        AppendBattleLog(
            "CHARGE",
            attacker.DisplayName +
            "  ->  " +
            target.DisplayName,
            "Player-entered final Charge total: " +
            result +
            ". Warboard did not interpret the physical dice or offer rerolls."
        );

        ResolveChargeRoll(
            attacker,
            target,
            result,
            false,
            0
        );
    }

    private void CancelTraditionalCharge()
    {
        if (traditionalChargeAttacker != null)
        {
            // The declaration itself counts as the attempted charge in the
            // normal phase flow. Cancel is therefore a UI escape before the
            // final result is submitted, not a second chance to charge.
            status =
                traditionalChargeAttacker.DisplayName +
                " charge declaration remains attempted; no result was entered.";
        }

        traditionalChargePending = false;
        traditionalChargeAttacker = null;
        traditionalChargeTarget = null;
    }

    private void BeginTraditionalReanimation(
        List<SquadController> eligible)
    {
        traditionalReanimationUnits.Clear();

        if (eligible != null)
        {
            traditionalReanimationUnits.AddRange(
                eligible.Where(
                    unit =>
                        unit != null &&
                        unit.IsAlive &&
                        unit.IsOnBattlefield &&
                        unit.HasAnyLostWoundsOrModels()
                )
            );
        }

        if (traditionalReanimationUnits.Count == 0)
        {
            traditionalReanimationPending = false;
            traditionalReanimationUnit = null;
            ContinueEndPhaseFlow();
            return;
        }

        traditionalReanimationPending = true;
        traditionalReanimationUnit =
            traditionalReanimationUnits[0];
        traditionalReanimationDeadIndex = 0;

        manualWoundEditMode = true;

        OpenTraditionalDicePrompt(
            1
        );

        AppendBattleLog(
            "REANIMATION",
            "Reanimation Protocols",
            "Traditional Reanimation window opened. Player resolves all Reanimation dice manually and directly edits returned/healed models."
        );

        status =
            "REANIMATION PROTOCOLS: resolve the tabletop roll yourself. Select a damaged unit, then manually heal or return models.";
    }

    private void SelectTraditionalReanimationUnit(
        SquadController unit)
    {
        if (!traditionalReanimationPending ||
            unit == null ||
            !traditionalReanimationUnits
                .Contains(
                    unit))
        {
            return;
        }

        traditionalReanimationUnit =
            unit;
        traditionalReanimationDeadIndex = 0;

        status =
            "REANIMATION: " +
            unit.DisplayName +
            " selected. Apply only the wounds/models your tabletop roll allows.";
    }

    private void TraditionalHealSelectedReanimationWound()
    {
        if (!traditionalReanimationPending ||
            traditionalReanimationUnit == null ||
            selectedModel == null ||
            !selectedModel.IsAlive ||
            selectedModel.Squad == null ||
            selectedModel.Squad
                .JoinedActionController() !=
                traditionalReanimationUnit
                    .JoinedActionController())
        {
            status =
                "Select a living model in the current Reanimation unit first.";
            return;
        }

        if (selectedModel.CurrentWounds >=
            selectedModel.MaxWounds)
        {
            status =
                selectedModel.RoleName +
                " is already at full wounds.";
            return;
        }

        int before =
            selectedModel.CurrentWounds;

        selectedModel.Heal(1);
        selectedModel.RefreshWoundDisplay();

        AppendBattleLog(
            "REANIMATION",
            traditionalReanimationUnit.DisplayName,
            selectedModel.RoleName +
            " manually restored 1 wound (" +
            before +
            "  ->  " +
            selectedModel.CurrentWounds +
            ")."
        );

        status =
            selectedModel.RoleName +
            " restored to " +
            selectedModel.CurrentWounds +
            "/" +
            selectedModel.MaxWounds +
            " wounds.";
    }

    private List<ModelToken>
        TraditionalReanimationDestroyedModels()
    {
        if (traditionalReanimationUnit == null)
        {
            return new List<ModelToken>();
        }

        return
            traditionalReanimationUnit
                .DestroyedModelTokens()
                .Where(
                    model =>
                        model != null
                )
                .ToList();
    }

    private void CycleTraditionalReanimationDeadModel(
        int direction)
    {
        List<ModelToken> dead =
            TraditionalReanimationDestroyedModels();

        if (dead.Count == 0)
        {
            traditionalReanimationDeadIndex = 0;
            return;
        }

        traditionalReanimationDeadIndex =
            (traditionalReanimationDeadIndex +
             direction) %
            dead.Count;

        if (traditionalReanimationDeadIndex < 0)
        {
            traditionalReanimationDeadIndex +=
                dead.Count;
        }
    }

    private void TraditionalReturnSelectedReanimationModel()
    {
        if (!traditionalReanimationPending ||
            traditionalReanimationUnit == null)
        {
            return;
        }

        List<ModelToken> dead =
            TraditionalReanimationDestroyedModels();

        if (dead.Count == 0)
        {
            status =
                traditionalReanimationUnit.DisplayName +
                " has no destroyed models to return.";
            return;
        }

        traditionalReanimationDeadIndex =
            Mathf.Clamp(
                traditionalReanimationDeadIndex,
                0,
                dead.Count - 1
            );

        ModelToken returning =
            dead[
                traditionalReanimationDeadIndex
            ];

        Vector3 position;

        if (!TryFindReanimationPosition(
                traditionalReanimationUnit,
                returning,
                out position))
        {
            status =
                "No legal automatic placement position was found for " +
                returning.RoleName +
                ".";
            return;
        }

        returning.Revive(
            1,
            position
        );

        traditionalReanimationUnit.RefreshVisuals();
        RefreshObjectiveDisplays();

        AppendBattleLog(
            "REANIMATION",
            traditionalReanimationUnit.DisplayName,
            returning.RoleName +
            " manually returned at 1 wound. Warboard did not determine whether the tabletop roll allowed this."
        );

        traditionalReanimationDeadIndex = 0;

        status =
            returning.RoleName +
            " returned at 1 wound.";
    }

    private void CompleteTraditionalReanimationUnit()
    {
        if (!traditionalReanimationPending ||
            traditionalReanimationUnit == null)
        {
            return;
        }

        SquadController completed =
            traditionalReanimationUnit;

        traditionalReanimationUnits.Remove(
            completed
        );

        AppendBattleLog(
            "REANIMATION",
            completed.DisplayName,
            "Player marked this unit's Reanimation Protocols resolution complete."
        );

        traditionalReanimationUnit =
            traditionalReanimationUnits
                .FirstOrDefault();

        traditionalReanimationDeadIndex = 0;

        if (traditionalReanimationUnit == null)
        {
            FinishTraditionalReanimation();
            return;
        }

        status =
            "REANIMATION: choose/resolve the next damaged unit.";
    }

    private void FinishTraditionalReanimation()
    {
        traditionalReanimationPending = false;
        traditionalReanimationUnit = null;
        traditionalReanimationUnits.Clear();
        traditionalReanimationDeadIndex = 0;

        manualWoundEditMode = false;

        AppendBattleLog(
            "REANIMATION",
            "Reanimation Protocols",
            "Player marked Traditional Reanimation resolution complete."
        );

        status =
            "Traditional Reanimation Protocols complete.";

        ContinueEndPhaseFlow();
    }

}
